CREATE TABLE bookings(
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),code varchar(24) NOT NULL UNIQUE,quote_id uuid NOT NULL UNIQUE REFERENCES pricing_quotes,departure_id uuid NOT NULL REFERENCES departures,guest_session_id uuid REFERENCES guest_sessions,created_by_staff_id uuid REFERENCES staff_users,customer_id uuid REFERENCES customers,
 source text NOT NULL CHECK(source IN('web','phone','counter')),status text NOT NULL DEFAULT 'pending' CHECK(status IN('pending','confirmed','expired','cancelled','completed')),payment_status text NOT NULL DEFAULT 'unpaid' CHECK(payment_status IN('unpaid','partially_paid','paid','refunded','partially_refunded')),
 contact jsonb NOT NULL,counts jsonb NOT NULL,seat_count int NOT NULL CHECK(seat_count>0 AND seat_count<=20),payment_option text NOT NULL CHECK(payment_option IN('full','deposit')),total_amount bigint NOT NULL CHECK(total_amount>0),deposit_amount bigint NOT NULL CHECK(deposit_amount>0 AND deposit_amount<=total_amount),paid_amount bigint NOT NULL DEFAULT 0 CHECK(paid_amount>=0 AND paid_amount<=total_amount),currency char(3) NOT NULL DEFAULT 'VND' CHECK(currency='VND'),
 price_snapshot jsonb NOT NULL,policy_snapshot jsonb NOT NULL,settings_snapshot jsonb NOT NULL,tour_snapshot jsonb NOT NULL,special_requests text NOT NULL DEFAULT '',consent jsonb NOT NULL,expires_at timestamptz NOT NULL,balance_due_at timestamptz NOT NULL,version int NOT NULL DEFAULT 1 CHECK(version>0),cancel_reason text,cancelled_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),CHECK((guest_session_id IS NOT NULL)::int+(created_by_staff_id IS NOT NULL)::int=1)
);
CREATE INDEX bookings_departure ON bookings(departure_id,status,id);CREATE INDEX bookings_created ON bookings(created_at,status);CREATE INDEX bookings_guest ON bookings(guest_session_id);
CREATE TABLE booking_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),booking_id uuid NOT NULL REFERENCES bookings,code text NOT NULL,label text NOT NULL,quantity int NOT NULL CHECK(quantity>=0),unit_amount bigint NOT NULL CHECK(unit_amount>=0),total_amount bigint NOT NULL CHECK(total_amount>=0),UNIQUE(booking_id,code));
CREATE TABLE booking_passengers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),booking_id uuid NOT NULL REFERENCES bookings,passenger_type text NOT NULL CHECK(passenger_type IN('adult','child','infant')),full_name varchar(120) NOT NULL,date_of_birth date NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE seat_holds(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),booking_id uuid NOT NULL UNIQUE REFERENCES bookings,departure_id uuid NOT NULL REFERENCES departures,seat_count int NOT NULL CHECK(seat_count>0),status text NOT NULL DEFAULT 'active' CHECK(status IN('active','converted','expired','released')),expires_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX holds_expiry ON seat_holds(departure_id,expires_at) WHERE status='active';
CREATE TABLE booking_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),booking_id uuid NOT NULL REFERENCES bookings,event_type text NOT NULL,actor_staff_id uuid REFERENCES staff_users,payload jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE booking_notes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),booking_id uuid NOT NULL REFERENCES bookings,staff_id uuid NOT NULL REFERENCES staff_users,body text NOT NULL CHECK(length(body) BETWEEN 1 AND 5000),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE idempotency_keys(principal text NOT NULL,route text NOT NULL,key uuid NOT NULL,request_hash text NOT NULL,response jsonb,status_code int NOT NULL DEFAULT 201,created_at timestamptz NOT NULL DEFAULT now(),expires_at timestamptz NOT NULL DEFAULT now()+interval '24 hours',PRIMARY KEY(principal,route,key));
CREATE TABLE booking_lookup_tokens(token_hash text PRIMARY KEY,booking_id uuid NOT NULL REFERENCES bookings,expires_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
